// The set's entry: a registry copy lands as one file, `hardware.tsx`, so this is the file a reader opens first. Every part
// stands beside it and is imported from here; the sheet arrives with them (`skin.css`, which brings `tokens-01.css`).
export { BarGraph, type BarGraphProps } from "./bar-graph.tsx";
export { Device, type DeviceProps } from "./device.tsx";
export { Dial, type DialProps } from "./dial.tsx";
export { BLACK_KEYS, Faceplate, type FaceplateProps, type KeyColor } from "./faceplate.tsx";
export { Fader, type FaderProps } from "./fader.tsx";
export { Key, type KeyProps } from "./key.tsx";
export { Lcd, type LcdProps } from "./lcd.tsx";
export { Led, type LedProps } from "./led.tsx";
export { Rocker, type RockerProps } from "./rocker.tsx";
export { SlideSwitch, type SlideSwitchProps } from "./slide-switch.tsx";

import type { JSX } from "@solidjs/web";

// The skin's sheet, imported once and only here: every part's look is scoped to `[data-skin="01"]`, which this panel is the
// one thing that sets, so a skin without a faceplate has nothing to paint.
import "./skin.css";

/**
 * A key colour: the one colour the whole skin is turned into roles from, as OKLCH. A dial's pointer, a key's cap, a lit lamp
 * and the focus ring are all derived from it (see `tokens-01.css`), so a host never picks a second colour.
 */
export interface KeyColor {
  /** Lightness, 0..1. Above 0.68 the key counts as light: its ink goes near-black and the colour comes back as a marker. */
  readonly l: number;
  /** Chroma, 0..~0.4. 0 is a neutral key. */
  readonly c: number;
  /** Hue in degrees, 0..360. */
  readonly h: number;
}

/** Black keys: the skin's default, and the same numbers the sheet starts from. */
export const BLACK_KEYS: KeyColor = { l: 0.24, c: 0, h: 0 };

export interface FaceplateProps {
  /** The printed legend across the top of the panel: the device's name, set small and spaced. */
  readonly title?: string | undefined;
  /** The panel's key colour (default `BLACK_KEYS`), which every part on it is derived from. */
  readonly keyColor?: KeyColor | undefined;
  readonly children?: JSX.Element;
}

/**
 * The moulded panel every part of skin 01 stands on: a light grey surface with a lit top edge, a rim of hairline and a shadow
 * tinted with the panel's own hue, carrying the one colour the rest of the skin derives from.
 *
 * It is also the skin's scope: `data-skin="01"` is set here and nowhere else, so a part outside a faceplate is deliberately
 * unpainted, and `keyColor` is written as the three numbers `tokens-01.css` reads (`--theme-l`, `--theme-c`, `--theme-h`).
 */
export const Faceplate = (props: FaceplateProps): JSX.Element => {
  const colour = (): KeyColor => props.keyColor ?? BLACK_KEYS;
  return (
    <div
      data-skin="01"
      data-part="faceplate"
      style={{
        "--theme-l": String(colour().l),
        "--theme-c": String(colour().c),
        "--theme-h": String(colour().h),
      }}
    >
      {props.title === undefined ? undefined : (
        <span data-part="faceplate-title">{props.title}</span>
      )}
      {props.children}
    </div>
  );
};

import {
  type Button as ButtonController,
  type ButtonOptions,
  createButton,
} from "@cssints/headless";
import type { JSX } from "@solidjs/web";
import { merge, untrack } from "solid-js";

export interface KeyProps extends Omit<ButtonOptions, "value" | "defaultValue" | "onValueChange"> {
  /**
   * The key's accessible name (`aria-label`). It is separate from `legend` because the panel prints abbreviations: a key
   * whose legend reads "MUTE" may be named "Mute the output".
   */
  readonly label: string;
  /** The printed legend on the cap (default: the label). */
  readonly legend?: string | undefined;
  /** Controlled: the host owns the latched state and this is the only thing that changes it. */
  readonly value?: boolean | undefined;
  /** Unlatched at mount; ignored while `value` is set. */
  readonly defaultValue?: boolean | undefined;
  /** A request to latch or release, called when the intent differs from the current state. */
  readonly onValueChange?: ((pressed: boolean) => void) | undefined;
  /** The primitive, once: a page that reads the latched state as well as shows it. */
  readonly onReady?: ((button: ButtonController) => void) | undefined;
}

/**
 * A key: a cap standing in its hole. `createButton` owns the activation — Enter, Space, pointer focus — and, with `isToggle`,
 * the latched state and its `aria-pressed`.
 *
 * The hole is the `<button>` itself and the cap is the child that moves: both carry a `data-part`, because the CA sheet draws
 * the recess on one and the travel, the wall and the shadow on the other. A command key returns to the raised position; a
 * latch (`isToggle`) stays down, and `aria-pressed` is the one bit of state the sheet reads for both.
 */
export const Key = (props: KeyProps): JSX.Element => {
  const button = createButton({
    get isToggle() {
      return props.isToggle;
    },
    get value() {
      return props.value;
    },
    get defaultValue() {
      return props.defaultValue;
    },
    get disabled() {
      return props.disabled;
    },
    get onClick() {
      return props.onClick;
    },
    get onValueChange() {
      return props.onValueChange;
    },
  });
  untrack(() => props.onReady)?.(button);

  const hole = merge(button.buttonProps, {
    "data-part": "key",
    get "aria-label"() {
      return props.label;
    },
  });

  return (
    <button {...hole}>
      <span data-part="key-face">
        <span data-part="key-legend">{props.legend ?? props.label}</span>
      </span>
    </button>
  );
};

import {
  createSwitch,
  type Switch as SwitchController,
  type SwitchOptions,
} from "@cssints/headless";
import type { JSX } from "@solidjs/web";
import { merge, untrack } from "solid-js";

export interface RockerProps extends Omit<
  SwitchOptions,
  "value" | "defaultValue" | "onValueChange" | "enterToggles"
> {
  /** The rocker's accessible name (`aria-label`); the two printed legends are its visible ends. */
  readonly label: string;
  /** The printed legend of the down end (default `"Off"`). */
  readonly offLabel?: string | undefined;
  /** The printed legend of the up end (default `"On"`). */
  readonly onLabel?: string | undefined;
  /** Controlled: the host owns the state and this is the only thing that changes it. */
  readonly value?: boolean | undefined;
  /** Off at mount; ignored while `value` is set. */
  readonly defaultValue?: boolean | undefined;
  /** A request to change the state, called when the intent differs from the current one. */
  readonly onValueChange?: ((checked: boolean) => void) | undefined;
  /** The primitive, once: a page that reads the state as well as shows it. */
  readonly onReady?: ((rocker: SwitchController) => void) | undefined;
}

/**
 * A two-position rocker: one rigid cap that tips, one end down and the other up. `createSwitch` owns the contract — Space and
 * Enter, the pointer, `aria-checked`, the read-only and disabled cases — and the sheet owns which end is down.
 *
 * The reported state is the whole of what the cap shows: `aria-checked` moves two wall heights, the cap rises by their
 * average and tips about its middle, and the legend of the chosen end is the one carrying the key's cap tone. Both ends print
 * a legend, so the choice is legible without colour.
 */
export const Rocker = (props: RockerProps): JSX.Element => {
  const rocker = createSwitch({
    get value() {
      return props.value;
    },
    get defaultValue() {
      return props.defaultValue;
    },
    get disabled() {
      return props.disabled;
    },
    get readOnly() {
      return props.readOnly;
    },
    get onValueChange() {
      return props.onValueChange;
    },
  });
  untrack(() => props.onReady)?.(rocker);

  const base = merge(rocker.switchProps, {
    "data-part": "rocker",
    get "aria-label"() {
      return props.label;
    },
  });

  return (
    <div {...base}>
      <span data-part="rocker-cap">
        <span data-part="rocker-legend" data-side="off">
          {props.offLabel ?? "Off"}
        </span>
        <span data-part="rocker-legend" data-side="on">
          {props.onLabel ?? "On"}
        </span>
      </span>
    </div>
  );
};

import {
  createSwitch,
  type Switch as SwitchController,
  type SwitchOptions,
} from "@cssints/headless";
import type { JSX } from "@solidjs/web";
import { merge, untrack } from "solid-js";

export interface SlideSwitchProps extends Omit<
  SwitchOptions,
  "value" | "defaultValue" | "onValueChange" | "enterToggles"
> {
  /** The switch's accessible name (`aria-label`); the two printed legends are its visible ends. */
  readonly label: string;
  /** The printed legend of the off end (default `"Off"`). */
  readonly offLabel?: string | undefined;
  /** The printed legend of the on end (default `"On"`). */
  readonly onLabel?: string | undefined;
  /** Controlled: the host owns the state and this is the only thing that changes it. */
  readonly value?: boolean | undefined;
  /** Off at mount; ignored while `value` is set. */
  readonly defaultValue?: boolean | undefined;
  /** A request to change the state, called when the intent differs from the current one. */
  readonly onValueChange?: ((checked: boolean) => void) | undefined;
  /** The primitive, once: a page that reads the state as well as shows it. */
  readonly onReady?: ((slide: SwitchController) => void) | undefined;
}

/**
 * A small slide switch: a lever in a recessed slot with a printed detent tick and a legend at each end. `createSwitch` owns
 * the contract (Space and Enter, the pointer press, `aria-checked`, the read-only and disabled cases); the sheet draws the
 * two positions and the snap between them.
 *
 * One thing this part cannot do: `createSwitch` reports a state, not a position. There is no pointer drag and no halfway
 * value to read, so the lever is at one end or the other — the finger does not carry it, and no detent is reported while it
 * moves. A dragged lever would need the primitive to expose the drag; the skin does not fake it with a CSS transition.
 */
export const SlideSwitch = (props: SlideSwitchProps): JSX.Element => {
  const slide = createSwitch({
    get value() {
      return props.value;
    },
    get defaultValue() {
      return props.defaultValue;
    },
    get disabled() {
      return props.disabled;
    },
    get readOnly() {
      return props.readOnly;
    },
    get onValueChange() {
      return props.onValueChange;
    },
  });
  untrack(() => props.onReady)?.(slide);

  const base = merge(slide.switchProps, {
    "data-part": "slide-switch",
    get "aria-label"() {
      return props.label;
    },
  });

  return (
    <div {...base}>
      <span data-part="slide-switch-slot">
        <span data-part="slide-switch-lever" aria-hidden="true" />
      </span>
      <span data-part="slide-switch-legend" data-side="off">
        {props.offLabel ?? "Off"}
      </span>
      <span data-part="slide-switch-legend" data-side="on">
        {props.onLabel ?? "On"}
      </span>
    </div>
  );
};

import {
  createSlider,
  type Slider as SliderController,
  type SliderOptions,
} from "@cssints/headless";
import type { JSX } from "@solidjs/web";
import { merge, untrack } from "solid-js";

export interface FaderProps extends Omit<SliderOptions, "id" | "orientation"> {
  /** The fader's name and its printed legend: the thumb is the `role="slider"`, and it needs a name. */
  readonly label: string;
  /** The primitive, once: a page that reads the value as well as shows it. */
  readonly onReady?: ((slider: SliderController) => void) | undefined;
}

/**
 * A fader: a groove with a printed scale under it and a ribbed cap on the value. `createSlider` owns the value, the bounds,
 * the step, the arrows, Home and End, the press on the groove and the drag; the sheet owns the groove, the printed ticks,
 * the fill and the cap.
 *
 * The cap is the announced `role="slider"` and the groove is the pointer surface that contains it, so a press anywhere on
 * the groove jumps and drags. The cap's position and the fill are the one thing a class cannot read off `aria-valuenow` (an
 * arithmetic turn of an attribute inside `calc()`), so both are an inline `--at` percentage of the same two numbers the thumb
 * announces, and they cannot disagree with the value a reader hears.
 */
export const Fader = (props: FaderProps): JSX.Element => {
  const slider = createSlider({
    get min() {
      return props.min;
    },
    get max() {
      return props.max;
    },
    get step() {
      return props.step;
    },
    get largeStep() {
      return props.largeStep;
    },
    get value() {
      return props.value;
    },
    get defaultValue() {
      return props.defaultValue;
    },
    get direction() {
      return props.direction;
    },
    get disabled() {
      return props.disabled;
    },
    get onValueChange() {
      return props.onValueChange;
    },
  });
  untrack(() => props.onReady)?.(slider);

  const at = (): number => {
    const min = Number(slider.thumbProps["aria-valuemin"]);
    const max = Number(slider.thumbProps["aria-valuemax"]);
    const now = Number(slider.thumbProps["aria-valuenow"]);
    // clamped: a host that hands the primitive a value outside its own bounds must not paint the cap off the groove
    const share = max > min ? ((now - min) / (max - min)) * 100 : 0;
    return Math.min(100, Math.max(0, share));
  };

  const groove = merge(slider.trackProps, {
    "data-part": "fader-track",
    get style() {
      return { "--at": String(at()) };
    },
  });
  const cap = merge(slider.thumbProps, {
    "data-part": "fader-cap",
    get "aria-label"() {
      return props.label;
    },
  });

  return (
    <div data-part="fader">
      <span data-part="fader-label">{props.label}</span>
      <div {...groove}>
        <span data-part="fader-fill" aria-hidden="true" />
        <span data-part="fader-scale" aria-hidden="true" />
        <div {...cap} />
      </div>
    </div>
  );
};

import { createKnob, type Knob as KnobController, type KnobOptions } from "@cssints/headless";
import type { JSX } from "@solidjs/web";
import { merge, untrack } from "solid-js";

export interface DialProps extends Omit<KnobOptions, "id" | "labels"> {
  /** The dial's name: it is the primitive's `labels.knob`, so it is both the accessible and the printed name. */
  readonly label: string;
  /** The dial's diameter in CSS. @default "5.5rem" */
  readonly size?: string | undefined;
  /** The primitive, once: a page that reads the value as well as shows it. */
  readonly onReady?: ((knob: KnobController) => void) | undefined;
}

const DEFAULT_SIZE = "5.5rem";
/** The pointer sweeps three quarters of a turn, from the bottom-left to the bottom-right of the dial. */
const SWEEP = 0.75;
const START_DEGREES = -135;

/**
 * A dial: a knurled crown with a printed arc around it and a pointer at the value. `createKnob` owns the value, the bounds,
 * the step, the three gestures (spin, or a slide either way), the wheel, the arrows, Page Up and Page Down, Home and End, and
 * every `aria-*` the dial announces; the sheet owns the crown, the printed ticks (a repeating conic gradient masked to a 6px
 * band) and the pointer.
 *
 * The pointer turns by `--turn`, an inline angle the primitive's own `percentOf` gives, and the readout is its
 * `aria-valuetext` — `format` is the one place the value is worded, for the eye and for the ear. The value itself is also in
 * the page as the primitive's live region, visually hidden and never `hidden`.
 */
export const Dial = (props: DialProps): JSX.Element => {
  const knob = createKnob({
    get min() {
      return props.min;
    },
    get max() {
      return props.max;
    },
    get step() {
      return props.step;
    },
    get value() {
      return props.value;
    },
    get defaultValue() {
      return props.defaultValue;
    },
    get wrap() {
      return props.wrap;
    },
    get gesture() {
      return props.gesture;
    },
    get format() {
      return props.format;
    },
    labels: { knob: props.label },
    get onValueChange() {
      return props.onValueChange;
    },
  });
  untrack(() => props.onReady)?.(knob);

  const turn = (): number =>
    Number((START_DEGREES + 360 * SWEEP * knob.percentOf(knob.value())).toFixed(3));

  const crown = merge(knob.knobProps, {
    "data-part": "dial-knob",
    get style() {
      const size = props.size ?? DEFAULT_SIZE;
      return {
        "--turn": String(turn()),
        width: size,
        height: size,
        "font-size": `calc(${size} / 6)`,
      };
    },
  });

  return (
    <div data-part="dial">
      <span data-part="dial-label">{props.label}</span>
      <div {...crown}>
        <span data-part="dial-scale" aria-hidden="true" />
        <span data-part="dial-pointer" aria-hidden="true" />
        <span data-part="dial-readout" aria-hidden="true">
          {knob.knobProps["aria-valuetext"]}
        </span>
      </div>
      <span {...knob.valueProps} data-part="dial-value">
        {knob.value()}
      </span>
    </div>
  );
};

import type { JSX } from "@solidjs/web";

export interface LcdProps {
  /** The printed tag over the glass: a static legend on the panel, not on the screen and not a live region. */
  readonly tag?: string | undefined;
  /**
   * The value the screen shows. It is the screen's live region — `role="status"`, `aria-live="polite"` — because a value
   * that changes is announced; a screen of static text is not (`children`).
   */
  readonly value?: string | undefined;
  /** Static text on the glass. It is never a live region: nothing announces it, because nothing changes it. */
  readonly children?: JSX.Element;
}

/**
 * The screen: a dark window sunk into the panel, its figure lit in the key's glow and its prose dim behind the glass. There is
 * no primitive behind it — a readout has no contract to keep — so this part is the one place the skin takes the live region
 * seriously itself: only `value` is one.
 *
 * The glass has two body slots because it has two voices: the figure is the lamp (`lcd-value`), anything else is prose
 * (`lcd-body`, the system sans). The tag is printed on the panel, above the well, like every other legend in this skin.
 */
export const Lcd = (props: LcdProps): JSX.Element => (
  <div data-part="lcd">
    {props.tag === undefined ? undefined : <span data-part="lcd-tag">{props.tag}</span>}
    <div data-part="lcd-screen">
      {props.value === undefined ? undefined : (
        <span data-part="lcd-value" role="status" aria-live="polite">
          {props.value}
        </span>
      )}
      {props.children === undefined ? undefined : (
        <span data-part="lcd-body">{props.children}</span>
      )}
    </div>
  </div>
);

import type { JSX } from "@solidjs/web";

export interface LedProps {
  /** The lamp's accessible name (`aria-label`), which is what a reader hears in place of the printed legend. */
  readonly label: string;
  /** Whether the lamp is lit. @default false */
  readonly on?: boolean | undefined;
  /** The printed legend beside the lamp; `label` when left out. */
  readonly legend?: string | undefined;
}

/**
 * A lamp: a small round lens in the panel, lit in the key colour at 0.86 lightness at most, so it still stands out from an
 * unlit one on the light panel. `role="img"` with a name, because a lamp is a picture of a state, not a control; the state
 * itself is `data-state`, which is both what the sheet paints and what a test reads.
 */
export const Led = (props: LedProps): JSX.Element => (
  <span
    data-part="led"
    role="img"
    aria-label={props.label}
    data-state={props.on === true ? "on" : "off"}
  >
    <span data-part="led-lamp" aria-hidden="true" />
    <span data-part="led-legend" aria-hidden="true">
      {props.legend ?? props.label}
    </span>
  </span>
);

import { createMeter, type Meter as MeterController, type MeterOptions } from "@cssints/headless";
import type { JSX } from "@solidjs/web";
import { For, merge, untrack } from "solid-js";

export interface BarGraphProps extends Omit<MeterOptions, "label"> {
  /** The graph's name: a `role="meter"` needs one. */
  readonly label: string;
  /** How many segments stand between the two ends. @default 12 */
  readonly segments?: number | undefined;
  /** The primitive, once: a page that reads the figure as well as shows it. */
  readonly onReady?: ((meter: MeterController) => void) | undefined;
}

const DEFAULT_SEGMENTS = 12;

/**
 * A bar graph: a row of segments, each lit or dark, filled up to the value. `createMeter` owns the figure, the bounds and the
 * announced `aria-valuenow` / `aria-valuetext`; the sheet owns the pitch, the ghost of an unlit segment and the glow of a
 * lit one.
 *
 * A segment's share is one number, `--v` (0 dark, 1 lit), which the sheet reads for the height of its lit column: how many
 * segments are lit is arithmetic over `aria-valuenow`, which CSS cannot do, so it is computed here from the primitive's own
 * percentage and written once on each segment. Nothing else about a segment is state.
 */
export const BarGraph = (props: BarGraphProps): JSX.Element => {
  const meter = createMeter({
    get value() {
      return props.value;
    },
    get min() {
      return props.min;
    },
    get max() {
      return props.max;
    },
    get valueText() {
      return props.valueText;
    },
    get labelId() {
      return props.labelId;
    },
    label: props.label,
  });
  untrack(() => props.onReady)?.(meter);

  const count = (): number => Math.max(1, props.segments ?? DEFAULT_SEGMENTS);
  const at = (index: number): number =>
    index < Math.round((meter.percent() / 100) * count()) ? 1 : 0;

  return (
    <div {...merge(meter.meterProps, { "data-part": "bar-graph" })}>
      <For each={Array.from({ length: count() }, (_, index) => index)}>
        {(index) => (
          <span
            data-part="bar-graph-segment"
            aria-hidden="true"
            style={{ "--v": String(at(index)) }}
          />
        )}
      </For>
    </div>
  );
};

import type { JSX } from "@solidjs/web";
import { createSignal } from "solid-js";

import { BarGraph } from "./bar-graph.tsx";
import { Dial } from "./dial.tsx";
import { Faceplate, type KeyColor } from "./faceplate.tsx";
import { Fader } from "./fader.tsx";
import { Key } from "./key.tsx";
import { Lcd } from "./lcd.tsx";
import { Led } from "./led.tsx";

export interface DeviceProps {
  /** The panel's key colour; every cap, the pointer, the lamp and the graph follow it. @default BLACK_KEYS */
  readonly keyColor?: KeyColor | undefined;
}

/** Ten percent a press: the two step keys are the coarse control, the fader the fine one. */
const STEP = 10;

/**
 * A dashboard faceplate: the screen and the signal graph across the top, the keys and the lamp under them, the fader and the
 * dial at the bottom. It is the set shown as one instrument, and the only stateful part of the skin — every value on it comes
 * from the primitives underneath, so the keys, the fader and the dial all move the same number and the screen shows it.
 */
export const Device = (props: DeviceProps): JSX.Element => {
  const [level, setLevel] = createSignal(40);
  const [muted, setMuted] = createSignal(false);
  const [tone, setTone] = createSignal(5);

  const nudge = (delta: number): void => {
    setLevel((value) => Math.min(100, Math.max(0, value + delta)));
  };

  return (
    <Faceplate title="Output unit 01" keyColor={props.keyColor}>
      <div data-part="device">
        <div data-part="device-row">
          <Lcd tag="Level" value={muted() ? "MUTED" : `${level()}%`} />
          <BarGraph label="Signal level" value={muted() ? 0 : level()} segments={12} />
        </div>
        <div data-part="device-row">
          <Key label="Lower the level" legend="−" onClick={() => nudge(-STEP)} />
          <Key
            label="Mute the output"
            legend="Mute"
            isToggle
            value={muted()}
            onValueChange={setMuted}
          />
          <Key label="Raise the level" legend="+" onClick={() => nudge(STEP)} />
          <Led label="Signal present" legend="Sig" on={!muted()} />
        </div>
        <div data-part="device-row">
          <Fader label="Level" min={0} max={100} value={level()} onValueChange={setLevel} />
          <Dial label="Tone" min={0} max={10} step={1} value={tone()} onValueChange={setTone} />
        </div>
      </div>
    </Faceplate>
  );
};

/* Skin 01, the pocket instrument: light moulded panels, keys standing in their holes, an LCD, lamps and printed scales.

   The shapes and the numbers are ported from SPEC-01's hardware skin (github.com/shuding/spec-01, MIT, Copyright (c) 2026
   Shu Ding). Each block names the reference file its geometry comes from; the selectors, class names and markup are ours, and
   every rule is scoped to `[data-skin="01"]`, which `Faceplate` puts on the panel. The colours come from `tokens-01.css`. */
@import "./tokens-01.css";

/* ---------- the faceplate: the moulded panel

   From `hardware-field.css`: one light grey panel, its lit top edge, a rim of a hairline and a shadow tinted with the panel's
   own hue. The printed title is the reference's `--label` (tiny, uppercase, spaced). */
[data-skin="01"][data-part="faceplate"] {
  display: grid;
  gap: 18px;
  padding: 18px;
  border-radius: calc(14px * var(--corner-scale));
  corner-shape: squircle;
  color: var(--ink);
  background:
    linear-gradient(180deg, rgb(255 255 255 / 0.55), rgb(255 255 255 / 0) 42%, rgb(0 0 0 / 0.03)),
    var(--panel);
  box-shadow:
    inset 0 1px 0 var(--panel-hi),
    0 0 0 1px hsl(var(--shadow-color) / 0.08),
    0 1px 0 #fff,
    0 8px 20px -6px hsl(var(--shadow-color) / 0.22);
  /* the panel reads as prose; what is printed on it is mono (--label), so a screen's text is not the same voice */
  font: 400 12px/1.4 var(--sans);
}

[data-skin="01"] [data-part="faceplate-title"] {
  font: var(--label);
  font-size: 10px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--ink);
  padding-block-end: 8px;
  border-block-end: 1px solid var(--line);
}

/* ---------- the key: a cap standing in its hole

   From `hardware-field.css` (the latching checkbox): one number, `--lift`, is how far the cap stands above its opening — the
   travel at rest, 0 latched, below that held down. The cap's position, every layer of its side wall and the shadow it casts
   are worked out from it, and only it animates, so the wall always reaches exactly down to the floor of the hole and the
   shadow list never changes length (a list that changes length flickers in Safari). The travel is ours (10px), the
   mechanism and the wall's 10 layers are the reference's.

   The button is the hole: a dark recess with a lit top rim of panel. The cap is the child that moves. */
[data-skin="01"] [data-part="key"] {
  --travel: 10px;
  --lift: var(--travel);
  appearance: none;
  display: grid;
  /* One footprint for every key on the panel, whatever its legend says: a latch cannot be told from a command key by its
     size. The legend truncates inside the cap; the state is the cap's seat, its marker and `aria-pressed`. */
  width: 68px;
  margin: 0;
  padding: calc(var(--travel) + 3px) 4px 3px;
  border: 0;
  border-radius: calc(14px * var(--corner-scale));
  corner-shape: squircle;
  background: var(--well);
  box-shadow:
    inset 0 3px 6px rgb(0 0 0 / 0.85),
    inset 0 -1px 0 rgb(255 255 255 / 0.06),
    0 1px 0 #fff,
    0 -1px 0 rgb(0 0 0 / 0.08);
  font: inherit;
  color: inherit;
  cursor: pointer;
  transition: --lift 140ms var(--ease-detent);
}

[data-skin="01"] [data-part="key-face"] {
  /* the cap: a lit top edge, a shade at its foot, the wall of its thickness, then the shadow it casts on the panel */
  --cap-lit: 0.18;
  --cap-shade: inset 0 -2px 2px rgb(0 0 0 / 0.45);
  position: relative;
  display: grid;
  place-items: center;
  min-height: 40px;
  padding: 0 8px;
  border-radius: calc(12px * var(--corner-scale));
  corner-shape: squircle;
  /* the colour is the cap; the gradient over it is the light falling on it */
  background-color: var(--key-color);
  background-image: linear-gradient(
    180deg,
    color-mix(in oklab, var(--key-color), #fff 14%),
    transparent 55%,
    color-mix(in oklab, var(--key-color), #000 12%)
  );
  box-shadow:
    inset 0 1px 0 rgb(255 255 255 / var(--cap-lit)),
    var(--cap-shade),
    0 calc(max(0px, var(--lift)) * 0.1) 0 color-mix(in oklab, var(--key-color), #000 30%),
    0 calc(max(0px, var(--lift)) * 0.2) 0 color-mix(in oklab, var(--key-color), #000 33%),
    0 calc(max(0px, var(--lift)) * 0.3) 0 color-mix(in oklab, var(--key-color), #000 36%),
    0 calc(max(0px, var(--lift)) * 0.4) 0 color-mix(in oklab, var(--key-color), #000 39%),
    0 calc(max(0px, var(--lift)) * 0.5) 0 color-mix(in oklab, var(--key-color), #000 42%),
    0 calc(max(0px, var(--lift)) * 0.6) 0 color-mix(in oklab, var(--key-color), #000 45%),
    0 calc(max(0px, var(--lift)) * 0.7) 0 color-mix(in oklab, var(--key-color), #000 48%),
    0 calc(max(0px, var(--lift)) * 0.8) 0 color-mix(in oklab, var(--key-color), #000 51%),
    0 calc(max(0px, var(--lift)) * 0.9) 0 color-mix(in oklab, var(--key-color), #000 54%),
    0 calc(max(0px, var(--lift)) * 1) 0 color-mix(in oklab, var(--key-color), #000 57%),
    0 calc(max(0px, var(--lift)) + 2px) calc(max(0px, var(--lift)) * 0.9 + 1px)
      hsl(var(--shadow-color) / 0.3);
  translate: 0 calc(var(--lift) * -1);
  transition:
    background 140ms,
    box-shadow 140ms;
}

/* The marker of a set latch: a lamp in the cap's own ink — the one colour that reads on the cap whatever the key is (white
   on a black key, near-black on a light one), with a glow in that same ink. A command key and an unset latch never show it. */
[data-skin="01"] [data-part="key-face"]::after {
  content: "";
  position: absolute;
  top: 6px;
  inset-inline-end: 6px;
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: var(--on-accent);
  opacity: 0;
  transition: opacity 140ms;
}
[data-skin="01"] [data-part="key"][aria-pressed="true"] [data-part="key-face"]::after {
  opacity: 1;
  box-shadow: 0 0 5px color-mix(in oklab, var(--on-accent) 55%, transparent);
}

/* the legend is printed on the cap, so it rides on the same number and sinks with it */
[data-skin="01"] [data-part="key-legend"] {
  font: var(--label);
  font-size: 9px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--on-accent);
  text-shadow: 0 1px 1px rgb(0 0 0 / 0.45);
  pointer-events: none;
}

/* latched: down on the floor of the hole, its top in shade */
[data-skin="01"] [data-part="key"][aria-pressed="true"] {
  --lift: 0px;
}
[data-skin="01"] [data-part="key"][aria-pressed="true"] [data-part="key-face"] {
  --cap-lit: 0.07;
  --cap-shade: inset 0 2px 6px rgb(0 0 0 / 0.5);
}
/* held: a pixel below the latched position */
[data-skin="01"] [data-part="key"]:active {
  --lift: -1px;
}
[data-skin="01"] [data-part="key"]:active [data-part="key-face"] {
  --cap-lit: 0.05;
  --cap-shade: inset 0 2px 6px rgb(0 0 0 / 0.55);
}
[data-skin="01"] [data-part="key"][aria-disabled="true"] {
  cursor: not-allowed;
  opacity: 0.55;
}

/* The ring is the ink, drawn outside the hole on the panel, and the ink is capped for a light key: 2 : 1 against the pale
   panel is the floor this actually clears by a wide margin, which the browser test measures. */
[data-skin="01"]
  :is([data-part="key"], [data-part="rocker"], [data-part="slide-switch"]):focus-visible,
[data-skin="01"] :is([data-part="fader-cap"], [data-part="dial-knob"]):focus-visible {
  outline: 2px solid var(--ring);
  outline-offset: 2px;
}

/* ---------- the rocker: a cap that tips between two positions

   From `hardware-rocker.css`: two wall heights, how far the cap's left and right ends stand above the panel, drive
   everything — the cap rises by their average and tips about its middle to meet both, so the pressed end goes down and the
   other comes up. A two-position rocker is the same cap with one of the two walls always shorter; `aria-checked` says which. */
@property --wall-l {
  syntax: "<length>";
  inherits: true;
  initial-value: 3px;
}

@property --wall-r {
  syntax: "<length>";
  inherits: true;
  initial-value: 3px;
}

[data-skin="01"] [data-part="rocker"] {
  --edge: 3px;
  --wall-l: var(--edge);
  --wall-r: calc(var(--edge) + 1.5px);
  --cap-w: 104px;
  --room: 4px;
  position: relative;
  display: inline-grid;
  min-width: var(--cap-w);
  min-height: 40px;
  padding: var(--room) 0 0;
  margin-block-start: calc(var(--room) * -1);
  border: 0;
  background: none;
  font: inherit;
  color: inherit;
  cursor: pointer;
  isolation: isolate;
  user-select: none;
  touch-action: manipulation;
  filter: drop-shadow(0 0 0.5px hsl(var(--shadow-color) / 0.45))
    drop-shadow(0 1px 0.5px hsl(var(--shadow-color) / 0.16))
    drop-shadow(0.5px 2px 3px hsl(var(--shadow-color) / 0.14));
  transition:
    --wall-l 80ms cubic-bezier(0.3, 0, 0.6, 1),
    --wall-r 80ms cubic-bezier(0.3, 0, 0.6, 1);
}

/* the base: the wall, the same shape as the cap, left in place */
[data-skin="01"] [data-part="rocker"]::before {
  content: "";
  position: absolute;
  inset: var(--room) 0 0;
  z-index: -1;
  border-radius: calc(11px * var(--corner-scale));
  corner-shape: squircle;
  background: linear-gradient(180deg, #dadad6, #cbcbc6);
}

[data-skin="01"] [data-part="rocker-cap"] {
  position: relative;
  display: flex;
  border-radius: calc(11px * var(--corner-scale));
  corner-shape: squircle;
  background:
    linear-gradient(0deg, rgb(255 255 255 / 0.55), rgb(255 255 255 / 0) 55%, rgb(0 0 0 / 0.025)),
    #f6f6f4;
  box-shadow:
    inset 0 1px 0 #fff,
    inset 0 -1px 0 rgb(0 0 0 / 0.04);
  translate: 0 calc((var(--wall-l) + var(--wall-r)) / -2);
  transform: skewY(atan2(var(--wall-l) - var(--wall-r), var(--cap-w)));
}

/* A rocker that is on has its ON end down: the left wall is short, the right one is long. */
[data-skin="01"] [data-part="rocker"][aria-checked="true"] {
  --wall-l: calc(var(--edge) - 1.5px);
  --wall-r: calc(var(--edge) + 1.5px);
}
[data-skin="01"] [data-part="rocker"]:active {
  --wall-l: 1px;
  --wall-r: 1px;
}

[data-skin="01"] [data-part="rocker-legend"] {
  display: grid;
  place-items: center;
  min-width: 52px;
  height: 40px;
  padding: 0 10px;
  border-radius: calc(11px * var(--corner-scale)) 0 0 calc(11px * var(--corner-scale));
  font: var(--label);
  font-size: 9px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  /* the end that is not set is dim print, not half-transparent ink: opacity halves the ratio (3.2 : 1) where a dim step
     keeps it at 7.9 : 1 on this cap */
  color: var(--dim);
  transition:
    color 160ms,
    background 160ms;
  pointer-events: none;
}
[data-skin="01"] [data-part="rocker-legend"][data-side="on"] {
  border-radius: 0 calc(11px * var(--corner-scale)) calc(11px * var(--corner-scale)) 0;
  /* the engraved line between the two positions: a groove with its lit far edge */
  box-shadow:
    inset 1px 0 0 rgb(0 0 0 / 0.13),
    inset 2px 0 0 rgb(255 255 255 / 0.95);
}
/* the chosen position is the one carrying the key's own cap tone and legend: not colour alone, the chip */
[data-skin="01"]
  [data-part="rocker"][aria-checked="false"]
  [data-part="rocker-legend"][data-side="off"],
[data-skin="01"]
  [data-part="rocker"][aria-checked="true"]
  [data-part="rocker-legend"][data-side="on"] {
  opacity: 1;
  color: var(--on-accent);
  background: var(--key-cap);
}

[data-skin="01"] :is([data-part="rocker"], [data-part="slide-switch"])[aria-disabled="true"] {
  opacity: 0.55;
  cursor: not-allowed;
}

/* ---------- the slide switch: a lever in a slot, with a printed detent

   From `hardware-slide-switch.css`: a recessed slot, a printed tick at each position and a ribbed lever that snaps to the
   chosen one (`--ease-detent`, so it stops dead at the detent). The primitive is a switch, not a drag: the lever follows
   `aria-checked`, and the thumb cannot report a position between the two — no gesture in `createSwitch` moves it, so this
   skin draws the two ends and the snap, never a finger halfway. */
[data-skin="01"] [data-part="slide-switch"] {
  position: relative;
  display: inline-grid;
  grid-template-columns: 1fr 1fr;
  justify-items: center;
  align-items: end;
  column-gap: 12px;
  row-gap: 9px;
  min-width: 64px;
  min-height: 40px;
  /* the room above the slot is the lever's throw: it stands out of it by 8px */
  padding: 8px 4px 0;
  border: 0;
  background: none;
  font: inherit;
  color: inherit;
  cursor: pointer;
  user-select: none;
  touch-action: manipulation;
}

[data-skin="01"] [data-part="slide-switch-slot"] {
  position: relative;
  grid-column: 1 / -1;
  width: 46px;
  height: 8px;
  border-radius: 3px;
  corner-shape: round;
  background: var(--groove);
  box-shadow:
    inset 0 1px 2px rgb(0 0 0 / 0.5),
    0 0 0 1px rgb(0 0 0 / 0.06),
    0 1px 0 1px rgb(255 255 255 / 0.8);
}

[data-skin="01"] [data-part="slide-switch-lever"] {
  position: absolute;
  top: -8px;
  left: 0;
  width: 20px;
  height: 24px;
  border-radius: calc(4px * var(--corner-scale));
  background:
    repeating-linear-gradient(90deg, rgb(0 0 0 / 0.12) 0 1px, transparent 1px 3px) center / 50% 60%
      no-repeat,
    linear-gradient(0deg, #fff, #efefec 70%, #e9e9e6);
  box-shadow:
    inset 0 1px 0 #fff,
    0 0 0 0.5px rgb(0 0 0 / 0.18),
    0 2px 0 #d2d2ce,
    0 2.5px 1px hsl(var(--shadow-color) / 0.14),
    0 4px 8px -3px hsl(var(--shadow-color) / 0.18);
  pointer-events: none;
  transition: left 300ms var(--ease-detent);
}
[data-skin="01"] [data-part="slide-switch"][aria-checked="true"] [data-part="slide-switch-lever"] {
  left: calc(100% - 20px);
}

[data-skin="01"] [data-part="slide-switch-legend"] {
  position: relative;
  font: var(--label);
  font-size: 8px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--dim);
  transition: color 160ms;
}
[data-skin="01"] [data-part="slide-switch-legend"]::before {
  content: "";
  position: absolute;
  top: -7px;
  left: calc(50% - 0.5px);
  width: 1px;
  height: 4px;
  background: var(--line);
}
/* the chosen position: its tick prints in the key's ink and its legend darkens */
[data-skin="01"]
  [data-part="slide-switch"][aria-checked="false"]
  [data-part="slide-switch-legend"][data-side="off"],
[data-skin="01"]
  [data-part="slide-switch"][aria-checked="true"]
  [data-part="slide-switch-legend"][data-side="on"] {
  color: var(--ink);
}
[data-skin="01"]
  [data-part="slide-switch"][aria-checked="false"]
  [data-part="slide-switch-legend"][data-side="off"]::before,
[data-skin="01"]
  [data-part="slide-switch"][aria-checked="true"]
  [data-part="slide-switch-legend"][data-side="on"]::before {
  background: var(--key-ink);
}

/* ---------- the fader: a groove, its printed scale and a ribbed cap

   From `hardware-field.css`: the printed slider scale (one 1px image per tick, placed at an exact percentage) and the
   reference's slider thumb, the ribbed cap. The scale is the whole run in one repeating gradient, so a tick lands every 5%
   without a wall of declarations. */
[data-skin="01"] [data-part="fader"] {
  display: grid;
  gap: 8px;
  /* it shares a row with the dial, so it takes what is left of it and no more */
  flex: 1 1 9rem;
  max-width: 20rem;
  min-width: 9rem;
}

[data-skin="01"] [data-part="fader-label"] {
  font: var(--label);
  font-size: 9px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--dim);
}

[data-skin="01"] [data-part="fader-track"] {
  position: relative;
  display: block;
  height: 10px;
  /* the room above is the cap's overhang; the room below is the printed scale, which the cap must not cross */
  margin-block: 14px 16px;
  border-radius: 3px;
  background: var(--slot);
  box-shadow:
    inset 0 1px 2px rgb(0 0 0 / 0.35),
    inset 0 -1px 0 rgb(255 255 255 / 0.5),
    0 1px 0 rgb(255 255 255 / 0.8);
  cursor: pointer;
  touch-action: none;
  user-select: none;
}

[data-skin="01"] [data-part="fader-track"] [data-part="fader-fill"] {
  position: absolute;
  inset-block: 0;
  left: 0;
  width: calc(var(--at) * 1%);
  border-radius: inherit;
  background: var(--key-color);
  pointer-events: none;
}

/* the printed scale, under the groove */
[data-skin="01"] [data-part="fader-scale"] {
  position: absolute;
  inset: auto 0 -15px;
  height: 7px;
  background: repeating-linear-gradient(90deg, var(--ink) 0 1px, transparent 1px calc(100% / 20));
  pointer-events: none;
}

[data-skin="01"] [data-part="fader-cap"] {
  position: absolute;
  top: 50%;
  left: calc(var(--at) * 1%);
  width: 22px;
  height: 26px;
  border-radius: calc(4px * var(--corner-scale));
  corner-shape: squircle;
  background:
    repeating-linear-gradient(90deg, rgb(0 0 0 / 0.12) 0 1px, transparent 1px 3px) center / 60% 40%
      no-repeat,
    linear-gradient(0deg, #fff, #efefec 70%, #e9e9e6);
  box-shadow:
    inset 0 1px 0 #fff,
    0 0 0 0.5px rgb(0 0 0 / 0.18),
    0 2px 0 #d2d2ce,
    0 2.5px 1px hsl(var(--shadow-color) / 0.14),
    0 4px 8px -3px hsl(var(--shadow-color) / 0.18);
  translate: -50% -50%;
  cursor: grab;
  touch-action: none;
  transition: left 120ms var(--ease-settle);
}
[data-skin="01"] [data-part="fader-cap"]:active {
  cursor: grabbing;
}

/* ---------- the dial: a printed arc and a pointer

   From `hardware-dials.css`: the tick arc around the crown (fine 0.7 deg marks on a 9 deg pitch, masked to a 6px band so the
   ticks are prints, not a ring) and the pointer as a whole-size box turned by an angle, its mark at the top. The reference
   masks the arc to its 270 deg sweep as a second mask layer; this dial has no stops — the primitive is continuous — so the
   arc prints the whole turn and the pointer is what shows the value. */
[data-skin="01"] [data-part="dial"] {
  --size: 5.5rem;
  position: relative;
  display: grid;
  justify-items: center;
  /* the arc stands 20px out of the crown, so the gap puts the label inside the arc's band and the label's own plate stops
     the ticks under the print: the scale and the name read as one instrument */
  gap: 14px;
  padding-inline: 22px;
}

[data-skin="01"] [data-part="dial-knob"] {
  position: relative;
  display: grid;
  place-items: center;
  width: var(--size);
  height: var(--size);
  border-radius: 50%;
  corner-shape: round;
  background: radial-gradient(120% 120% at 35% 25%, #fff, #e9e8e4 60%, #dcdbd6);
  box-shadow:
    inset 0 1px 0 #fff,
    0 0 0 4px #d9d8d3,
    0 0 0 4.5px rgb(0 0 0 / 0.08),
    0 3px 0 4px #c4c3be,
    0 3px 0 4.5px rgb(0 0 0 / 0.1),
    0.5px 4px 2px 4px hsl(var(--shadow-color) / 0.2),
    1px 8px 14px 1px hsl(var(--shadow-color) / 0.18);
  cursor: grab;
  touch-action: none;
  user-select: none;
  outline: none;
}
[data-skin="01"] [data-part="dial-knob"]:active {
  cursor: grabbing;
}

[data-skin="01"] [data-part="dial-scale"] {
  position: absolute;
  /* past the crown's rings (they reach 9px out), so the ticks are printed on the panel, not on the rim */
  inset: -20px;
  border-radius: 50%;
  /* 36 ticks round the turn, each a hair of print: one pixel of arc at this radius, so they read evenly */
  background: repeating-conic-gradient(from -0.5deg, var(--ink) 0deg 1deg, transparent 1deg 10deg);
  mask: radial-gradient(
    closest-side,
    transparent calc(100% - 7px),
    #000 calc(100% - 7px) calc(100% - 1px),
    transparent 100%
  );
  pointer-events: none;
}

[data-skin="01"] [data-part="dial-pointer"] {
  position: absolute;
  inset: 0;
  rotate: calc(var(--turn) * 1deg);
  transition: rotate 240ms var(--ease-detent);
  pointer-events: none;
}
[data-skin="01"] [data-part="dial-pointer"]::before {
  content: "";
  position: absolute;
  /* a share of the crown, not a fixed length: the mark clears the figure at every `size` */
  top: 8%;
  left: 50%;
  width: 3px;
  height: 18%;
  margin-left: -1.5px;
  border-radius: 2px;
  background: var(--key-color);
}

[data-skin="01"] [data-part="dial-readout"] {
  /* sized from the crown: one `size` prop moves the dial and its figure together */
  font: 600 1em/1 var(--mono);
  font-variant-numeric: tabular-nums;
  color: var(--ink);
  /* the reference's highlighter: the key colour behind the value for a light key, transparent for every other */
  background: var(--key-highlight);
  pointer-events: none;
}

[data-skin="01"] [data-part="dial-label"] {
  position: relative;
  z-index: 1;
  padding-inline: 6px;
  /* the plate the print sits on: the ticks of the arc stop under it instead of crossing the letters */
  background: var(--panel);
  font: var(--label);
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--dim);
}

/* a live value is in the page and out of sight: never `hidden`, which would stop it being announced */
[data-skin="01"] [data-part="dial-value"] {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
}

/* ---------- the LCD: a dark well with emissive print

   From `hardware-lcd.css`: the well the glass sits in (an inset well, its print a hair above the glass) and the label as a
   printed tag. The screen itself is ours: the reference's is grey reflective glass, this one is a dark window — the value is
   lit rather than printed, in the key's glow, and the grid the panel prints under its figures is confined to the figure, not
   laid over the whole screen. The tag is outside the glass, printed on the panel like every other legend here. */
[data-skin="01"] [data-part="lcd"] {
  display: inline-grid;
  gap: 6px;
  min-width: 7.5rem;
}

[data-skin="01"] [data-part="lcd-tag"] {
  font: var(--label);
  font-size: 8px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--dim);
}

[data-skin="01"] [data-part="lcd-screen"] {
  display: grid;
  gap: 5px;
  padding: 10px 14px 9px;
  border-radius: calc(6px * var(--corner-scale));
  corner-shape: squircle;
  background-color: var(--glass-base);
  background-image: var(--glass);
  box-shadow: var(--glass-well);
  font-family: var(--mono);
}

[data-skin="01"] [data-part="lcd-value"] {
  padding-block: 1px;
  /* the panel's grid, under the figure and nowhere else: 1px hairlines on a 4px pitch, at a fortieth of the print */
  background:
    repeating-linear-gradient(0deg, var(--glass-ghost) 0 1px, transparent 1px 4px),
    repeating-linear-gradient(90deg, var(--glass-ghost) 0 1px, transparent 1px 4px);
  font: 400 26px/1 var(--mono);
  font-variant-numeric: tabular-nums;
  letter-spacing: 0.02em;
  color: var(--key-glow);
  /* a slight bloom, the same colour as the print: a lamp behind the glass, not a drop shadow */
  text-shadow:
    0 0 4px color-mix(in oklab, var(--key-glow) 34%, transparent),
    0 0 10px color-mix(in oklab, var(--key-glow) 12%, transparent);
}

/* prose on the glass: the system sans, dim, with no bloom — only the figure is lit */
[data-skin="01"] [data-part="lcd-body"] {
  font: 400 12px/1.4 var(--sans);
  letter-spacing: 0.01em;
  color: var(--glass-dim);
}

/* ---------- the lamp

   From `tokens.css`: a lit lamp is the key colour at 0.86 lightness at most, so it still stands off the panel; unlit it is
   the hole it sits in. */
[data-skin="01"] [data-part="led"] {
  display: inline-flex;
  align-items: center;
  gap: 7px;
}

[data-skin="01"] [data-part="led-lamp"] {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: rgb(190 190 186);
  box-shadow:
    inset 0 1px 1px rgb(0 0 0 / 0.3),
    0 0 0 1px rgb(0 0 0 / 0.18),
    0 1px 0 rgb(255 255 255 / 0.8);
}

[data-skin="01"] [data-part="led"][data-state="on"] [data-part="led-lamp"] {
  /* a lit lens has a specular dot in it: that, not only the colour, is what tells it from an unlit one */
  background:
    radial-gradient(circle at 35% 30%, rgb(255 255 255 / 0.6), transparent 55%), var(--key-lamp);
  box-shadow:
    0 0 1px var(--key-lamp),
    0 0 6px color-mix(in oklab, var(--key-lamp) 70%, transparent),
    inset 0 1px 1px rgb(255 255 255 / 0.4);
}

[data-skin="01"] [data-part="led-legend"] {
  font: var(--label);
  font-size: 8px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--dim);
}

/* ---------- the bar graph: segments lit in the key's glow

   From `hardware-bar-graph.css`: 2px lit segments on a 4px pitch, both the ghost and the lit part counted from the foot so
   the lit segments sit exactly on the ghost ones, and a two-step glow that merges a lit column into one. The graph stands on
   a dark screen, so it lights with `--key-glow`, not the panel's lamp. */
[data-skin="01"] [data-part="bar-graph"] {
  --pitch: 4px;
  --segment: calc(var(--pitch) / 2);
  /* an unlit segment is a slot in the screen, not a black gap */
  --ghost: rgb(242 242 238 / 0.07);
  /* a lit one is a lamp: the key's glow pulled a little off white, so a bar of them has a body and not a caret's edge */
  --lit: color-mix(in oklab, var(--key-glow) 86%, #b3b1a9);
  display: grid;
  grid-auto-flow: column;
  grid-auto-columns: minmax(0, 1fr);
  gap: 3px;
  /* it is the widest thing on a device's row: it takes the room beside the screen */
  flex: 1 1 10rem;
  width: 100%;
  block-size: calc(var(--pitch) * 10);
  padding: 8px 10px;
  border-radius: calc(5px * var(--corner-scale));
  corner-shape: squircle;
  /* a screen sunk into the panel: dark at the top lip, a lit lower edge, no outer shadow to lift it off the surface */
  background: var(--screen);
  box-shadow:
    inset 0 2px 6px rgb(0 0 0 / 0.65),
    inset 0 0 0 1px rgb(0 0 0 / 0.4),
    0 1px 0 rgb(255 255 255 / 0.9);
}

[data-skin="01"] [data-part="bar-graph-segment"] {
  position: relative;
  background: repeating-linear-gradient(
    0deg,
    var(--ghost) 0 var(--segment),
    transparent var(--segment) var(--pitch)
  );
}

[data-skin="01"] [data-part="bar-graph-segment"]::after {
  content: "";
  position: absolute;
  inset: auto 0 0;
  height: calc(var(--v) * 100%);
  background: repeating-linear-gradient(
    0deg,
    var(--key-glow) 0 var(--segment),
    transparent var(--segment) var(--pitch)
  );
  filter: drop-shadow(0 0 1.5px color-mix(in oklab, var(--key-glow) 80%, transparent))
    drop-shadow(0 0 5px color-mix(in oklab, var(--key-glow) 45%, transparent));
  transition: height 240ms var(--ease-settle);
}

/* ---------- the device: the faceplate that shows the set

   A dashboard: the readout across the top, the keys and the lamp under it, the two continuous controls and the graph below. */
[data-skin="01"] [data-part="device"] {
  display: grid;
  gap: 18px;
}

[data-skin="01"] [data-part="device-row"] {
  display: flex;
  flex-wrap: wrap;
  align-items: flex-end;
  gap: 18px;
}

/* ---------- motion

   The key's travel and the dial's easing are the two things the reference asks to be dropped when motion is reduced: the
   cap changes position in one step, and the pointer is already at its value. */
@media (prefers-reduced-motion: reduce) {
  [data-skin="01"] [data-part="key"],
  [data-skin="01"] [data-part="key-face"],
  [data-skin="01"] [data-part="rocker"],
  [data-skin="01"] [data-part="slide-switch-lever"],
  [data-skin="01"] [data-part="fader-cap"],
  [data-skin="01"] [data-part="dial-pointer"],
  [data-skin="01"] [data-part="bar-graph-segment"]::after {
    transition: none;
  }
}

/* The one colour of skin 01, as the roles it is turned into.

   Ported from SPEC-01's hardware skin, `tokens.css` (github.com/shuding/spec-01, MIT, Copyright (c) 2026 Shu Ding). The rule
   is the reference's, restated on our own property names; the panel greys below it are ours.

   One colour in, six roles out, all worked out with relative colour syntax, so a host writes an OKLCH lightness, chroma and
   hue (`--theme-l`, `--theme-c`, `--theme-h`, set inline by `Faceplate`'s `keyColor`):

   - `--key-color`, the theme itself: caps, wedges, fills, anything large.
   - `--key-ink`: text and thin marks on the light panel, its lightness capped at 0.62 so a light key still reads. A key above
     0.68 lightness (yellow, a bright green) cannot be darkened into a readable ink and still look like itself, so its ink goes
     near-black and the key colour comes back as a marker instead.
   - `--key-highlight`: that marker. The key colour for a light key, transparent for every other, so a rule can lay it behind
     a value unconditionally.
   - `--key-cap`: the fill that carries a small legend (the rocker's chosen end). It is the key colour: the legend on it is
     `--on-accent`, which is chosen against the cap, so the cap never has to be darkened to make white read.
   - `--key-lamp`: a lit lamp on the panel, the key colour but never lighter than 0.86, so it still stands off the panel.
   - `--key-glow`: lit things on a dark screen, never darker than 0.72; a key with no chroma (black) lights near-white.
   - `--on-accent`: the text on a `--key-cap` or a key's cap. Pure white or pure black, switching at the lightness where the
     two cross (0.56 here, 0.179 relative luminance): one of them always clears 4.5 : 1, which is what an 8-10 px legend
     needs. The reference switches at 0.8, which leaves a *white* legend at 3.35 : 1 on a mid-light key (0.62), so a legible
     device legend could not be built on it.
   - `--ring`: the focus ring, which is the ink — the ring has to stand off the *panel*, and the ink is already capped for a
     light key, so the two are the same colour by construction and a light key can never paint an invisible ring.

   `clamp(0, (l - 0.68) * 1000, 1)` is a switch: 0 for a key at or below 0.68 lightness, 1 above. `--key-tone` is the same
   switch on `--theme-l`, for the one place it is used outside a colour. */

/* How far a key's cap stands out of its hole, and the one thing its travel animates: the cap's position, every layer of its
   side wall and the shadow it casts are worked out from it, so the wall always reaches exactly down to the opening. Only a
   registered property can be interpolated. */
@property --lift {
  syntax: "<length>";
  inherits: true;
  initial-value: 0px;
}

[data-skin="01"] {
  --theme-l: 0.24;
  --theme-c: 0;
  --theme-h: 0;
  --theme: oklch(var(--theme-l) var(--theme-c) var(--theme-h));
  --key-tone: clamp(0, (var(--theme-l) - 0.68) * 1000, 1);

  --key-color: var(--theme);
  --key-ink: oklch(
    from var(--theme)
      calc(
        min(l, 0.62) * (1 - clamp(0, (l - 0.68) * 1000, 1)) + 0.22 * clamp(0, (l - 0.68) * 1000, 1)
      )
      calc(c * (1 - clamp(0, (l - 0.68) * 1000, 1)) + 0.01 * clamp(0, (l - 0.68) * 1000, 1)) h
  );
  --key-highlight: color-mix(in oklab, var(--theme) calc(var(--key-tone) * 100%), transparent);
  --key-cap: var(--key-color);
  --key-lamp: oklch(from var(--theme) min(l, 0.86) c h);
  --key-glow: oklch(from var(--theme) max(l, calc(0.95 - 0.23 * clamp(0, c * 20, 1))) c h);
  --on-accent: oklch(calc(1 - clamp(0, (var(--theme-l) - 0.56) * 1000, 1)) 0 0);
  --ring: var(--key-ink);

  /* The panel: one light moulded grey, its lit top edge, the printed hairlines and the ink they are printed in. The dim tone
     is much darker than the reference's (#7a7a76), which is 2.9 : 1 on this panel: every legend here is real 8-10 px text,
     so it clears 4.5 : 1 with room (#4c4c48 is 6.1 : 1) and still sits a clear step under `--ink` (11.9 : 1). */
  --paper: #f3f3f1;
  --panel: #d9d9d6;
  --panel-hi: #e6e6e3;
  --line: #b4b4b0;
  --ink: #1d1d1c;
  --dim: #4c4c48;

  /* The hole a key stands in, the dark glass of the screen, the darker screen of the bar graph, the groove of a switch and
     the light slot of a fader. A screen is a well in the panel, not a light surface: what is on it is emissive print. */
  --well: linear-gradient(180deg, #0b0b0a, #1a1a19);
  --glass-base: #191a1d;
  --glass: linear-gradient(180deg, #202124, #141518);
  --glass-ink: #f2f2ee;
  --glass-dim: rgb(242 242 238 / 0.62);
  --glass-ghost: rgb(242 242 238 / 0.045);
  --glass-well: inset 0 2px 6px rgb(0 0 0 / 0.7), inset 0 0 0 1px rgb(0 0 0 / 0.45);
  --screen: linear-gradient(180deg, #17181a, #101113 60%);
  --groove: linear-gradient(180deg, #1b1b1a, #2c2c2a);
  --slot: linear-gradient(180deg, #c9c9c5, #dededa);

  /* The reference's shadows: one light above and to the left, so a soft shadow falls right and down at 1:2 and is tinted
     with the panel's own warm hue instead of black. A key's hard side wall is its thickness and stays straight down. */
  --shadow-color: 45deg 8% 30%;

  /* The printed legends are the only mono text on the panel: caps, printed scales, key legends, the dial's name. Prose on a
     screen is the system sans, so the two never read as the same voice. No web font: the workspace ships no mono face. */
  --mono: ui-monospace, SFMono-Regular, Menlo, monospace;
  --sans: system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  --label: 500 9px/1.2 var(--mono);

  /* A squircle's curve is shorter than a circle's at the same radius, so where corners are squircles every radius grows to
     keep the corner its visual size. */
  --corner-scale: 1;
  --key-radius: calc(10px * var(--corner-scale));

  /* The two easings of the reference: `detent` for anything that snaps to a position (a key, a lever, a dial's pointer) — a
     moment's resistance, then a quick travel that stops dead; `settle` for things that do not click (a screen, a meter). */
  --ease-detent: cubic-bezier(0.45, 0, 0.15, 1);
  --ease-settle: cubic-bezier(0.2, 0.8, 0.2, 1);
}

@supports (corner-shape: squircle) {
  [data-skin="01"] {
    --corner-scale: 2;
  }
}

/* WebKit flashes a grey box over anything tapped; the skin draws its own pressed states. */
[data-skin="01"] {
  -webkit-tap-highlight-color: transparent;
}

import type { JSX } from "@solidjs/web";
import { render } from "@solidjs/web";
import { For } from "solid-js";
import { afterEach, describe, expect, it } from "vite-plus/test";
import { userEvent } from "vite-plus/test/browser";

import { BarGraph } from "./bar-graph.tsx";
import { Device } from "./device.tsx";
import { Dial } from "./dial.tsx";
import { Faceplate } from "./faceplate.tsx";
import { Fader } from "./fader.tsx";
import { Key } from "./key.tsx";
import { Lcd } from "./lcd.tsx";
import { Led } from "./led.tsx";
import { Rocker } from "./rocker.tsx";
import { SlideSwitch } from "./slide-switch.tsx";

// The skin's own oracle: the primitives are checked in packages/headless, so this file never re-walks a pattern. It reads
// what the sheet hangs off their announced state (`aria-pressed`, `aria-checked`, `aria-valuenow`, `role`) and drives them.

/** Solid applies setters and delegated events on a later tick; two frames let the paint settle before a style is read. */
const frame = (): Promise<void> =>
  new Promise((resolve) => requestAnimationFrame(() => requestAnimationFrame(() => resolve())));

/** Polls until `done` holds, so the cap's travel is waited for rather than assumed. */
const waitFor = async (done: () => boolean, limit = 2000): Promise<void> => {
  const start = performance.now();
  while (!done()) {
    if (performance.now() - start > limit) {
      throw new Error("waitFor timed out");
    }
    await frame();
  }
};

const lift = (element: HTMLElement): string =>
  getComputedStyle(element).getPropertyValue("--lift").trim();

interface Mounted {
  readonly root: HTMLElement;
  readonly dispose: () => void;
}

const mounted: Mounted[] = [];

const mount = (view: () => JSX.Element): Mounted => {
  const root = document.createElement("div");
  document.body.append(root);
  const dispose = render(view, root);
  const instance: Mounted = {
    root,
    dispose: () => {
      dispose();
      root.remove();
    },
  };
  mounted.push(instance);
  return instance;
};

afterEach(() => {
  for (const instance of mounted.splice(0)) {
    instance.dispose();
  }
});

const part = (root: ParentNode, name: string): HTMLElement => {
  const element = root.querySelector<HTMLElement>(`[data-part="${name}"]`);
  if (element === null) {
    throw new Error(`skin 01: no part "${name}"`);
  }
  return element;
};

/** Tabs in from nowhere, so the ring is the browser's `:focus-visible` and not a forced class. */
const tabTo = async (root: ParentNode, name: string): Promise<HTMLElement> => {
  (document.activeElement as HTMLElement | null)?.blur();
  await frame();
  await userEvent.keyboard("{Tab}");
  await frame();
  const element = part(root, name);
  expect(document.activeElement).toBe(element);
  return element;
};

// Contrast, as WCAG computes it: the colour is painted and read back, because a computed `oklch(...)` is not `rgb(...)`.
const canvas = document.createElement("canvas");
canvas.width = 1;
canvas.height = 1;
const context = canvas.getContext("2d", { willReadFrequently: true });

const channels = (colour: string): readonly [number, number, number] => {
  if (context === null) {
    throw new Error("skin 01: no 2d context");
  }
  context.clearRect(0, 0, 1, 1);
  context.fillStyle = colour;
  context.fillRect(0, 0, 1, 1);
  const pixels = context.getImageData(0, 0, 1, 1).data;
  return [pixels[0] ?? 0, pixels[1] ?? 0, pixels[2] ?? 0];
};

const linear = (channel: number): number => {
  const value = channel / 255;
  return value <= 0.04045 ? value / 12.92 : ((value + 0.055) / 1.055) ** 2.4;
};

const luminance = (colour: string): number => {
  const [red, green, blue] = channels(colour);
  return 0.2126 * linear(red) + 0.7152 * linear(green) + 0.0722 * linear(blue);
};

const contrastRatio = (a: string, b: string): number => {
  const [lighter, darker] = [luminance(a), luminance(b)].sort((x, y) => y - x) as [number, number];
  return (lighter + 0.05) / (darker + 0.05);
};

/**
 * The colour a reader sees: the text's colour painted over its backdrop at the element's whole opacity chain (the fill is
 * done in a canvas, so a colour with alpha and an ancestor's `opacity` both land in the pixel, as they do on screen).
 */
const painted = (colour: string, backdrop: string, opacity: number): string => {
  if (context === null) {
    throw new Error("skin 01: no 2d context");
  }
  context.globalAlpha = 1;
  context.clearRect(0, 0, 1, 1);
  context.fillStyle = backdrop;
  context.fillRect(0, 0, 1, 1);
  context.globalAlpha = opacity;
  context.fillStyle = colour;
  context.fillRect(0, 0, 1, 1);
  context.globalAlpha = 1;
  const pixels = context.getImageData(0, 0, 1, 1).data;
  return `rgb(${pixels[0] ?? 0} ${pixels[1] ?? 0} ${pixels[2] ?? 0})`;
};

/** How much of the legend reaches the screen: `opacity` is inert on an ancestor as much as on the text itself. */
const opacityOf = (element: HTMLElement): number => {
  let opacity = 1;
  for (
    let current: HTMLElement | null = element;
    current !== null;
    current = current.parentElement
  ) {
    opacity *= Number(getComputedStyle(current).opacity);
  }
  return opacity;
};

const TRANSPARENT = /^rgba\([^)]*,\s*0\)$/;

/** The panel a ring stands on: the first opaque ancestor's background (the faceplate's own panel). */
const panelOf = (element: HTMLElement): string => {
  for (
    let current: HTMLElement | null = element;
    current !== null;
    current = current.parentElement
  ) {
    const colour = getComputedStyle(current).backgroundColor;
    if (colour !== "transparent" && !TRANSPARENT.test(colour)) {
      return colour;
    }
  }
  return "white";
};

describe("the set", () => {
  it("gives every part of the skin its name", () => {
    const { root } = mount(() => (
      <Faceplate title="Test unit">
        <Lcd tag="Level" value="40%">
          take 3
        </Lcd>
        <Led label="Signal present" legend="Sig" on />
        <BarGraph label="Signal level" value={50} segments={10} />
        <Key label="Mute the output" legend="Mute" isToggle />
        <Rocker label="Power" />
        <SlideSwitch label="Phantom power" />
        <Fader label="Level" min={0} max={100} defaultValue={40} />
        <Dial label="Tone" min={0} max={10} defaultValue={5} />
      </Faceplate>
    ));

    for (const name of [
      "faceplate",
      "faceplate-title",
      "lcd",
      "lcd-tag",
      "lcd-screen",
      "lcd-value",
      "lcd-body",
      "led",
      "led-lamp",
      "led-legend",
      "bar-graph",
      "bar-graph-segment",
      "key",
      "key-face",
      "key-legend",
      "rocker",
      "rocker-cap",
      "rocker-legend",
      "slide-switch",
      "slide-switch-slot",
      "slide-switch-lever",
      "slide-switch-legend",
      "fader",
      "fader-label",
      "fader-track",
      "fader-fill",
      "fader-scale",
      "fader-cap",
      "dial",
      "dial-label",
      "dial-knob",
      "dial-scale",
      "dial-pointer",
      "dial-readout",
      "dial-value",
    ]) {
      expect(root.querySelector(`[data-part="${name}"]`), name).not.toBeNull();
    }
  });

  it("makes a whole instrument out of the parts", () => {
    const { root } = mount(() => <Device />);
    expect(root.querySelector('[data-part="device"]')).not.toBeNull();
    expect(root.querySelectorAll('[data-part="key"]')).toHaveLength(3);
    expect(part(root, "lcd-value").getAttribute("role")).toBe("status");
  });

  it("makes the value a live region and the printed legend nothing of the sort", () => {
    const { root } = mount(() => (
      <Faceplate>
        <Lcd tag="Level" value="40%">
          take 3
        </Lcd>
      </Faceplate>
    ));

    const value = part(root, "lcd-value");
    expect(value.getAttribute("role")).toBe("status");
    expect(value.getAttribute("aria-live")).toBe("polite");
    for (const staticPart of [part(root, "lcd-tag"), part(root, "lcd-body")]) {
      expect(staticPart.getAttribute("role")).toBeNull();
      expect(staticPart.getAttribute("aria-live")).toBeNull();
    }
  });

  it("keeps the small switches' targets above 24 px (2.5.8)", () => {
    const { root } = mount(() => (
      <Faceplate>
        <Rocker label="Power" />
        <SlideSwitch label="Phantom power" offLabel="Off" onLabel="48V" />
      </Faceplate>
    ));
    for (const name of ["rocker", "slide-switch"]) {
      const box = part(root, name).getBoundingClientRect();
      expect(box.width, name).toBeGreaterThanOrEqual(24);
      expect(box.height, name).toBeGreaterThanOrEqual(24);
    }
  });

  it("lights a lamp in its state and names it", () => {
    const { root } = mount(() => (
      <Faceplate>
        <Led label="Signal present" legend="Sig" on />
        <Led label="Peak" legend="Peak" />
      </Faceplate>
    ));
    const [lit, dark] = [...root.querySelectorAll<HTMLElement>('[data-part="led"]')];
    expect(lit?.getAttribute("role")).toBe("img");
    expect(lit?.getAttribute("aria-label")).toBe("Signal present");
    expect(lit?.dataset.state).toBe("on");
    expect(dark?.dataset.state).toBe("off");
  });

  it("fills the graph's segments up to the value and sits in the panel", () => {
    const { root } = mount(() => (
      <Faceplate>
        <BarGraph label="Signal level" value={50} segments={10} />
      </Faceplate>
    ));
    const graph = part(root, "bar-graph");
    expect(graph.getAttribute("role")).toBe("meter");
    expect(graph.getAttribute("aria-valuenow")).toBe("50");
    const lit = [...graph.querySelectorAll<HTMLElement>('[data-part="bar-graph-segment"]')].map(
      (segment) => segment.style.getPropertyValue("--v"),
    );
    expect(lit.filter((value) => value === "1")).toHaveLength(5);
    expect([...graph.children]).toHaveLength(10);
    // the graph is the widest thing on the row: it takes the room the screen leaves
    expect(getComputedStyle(graph).flexGrow).toBe("1");
  });
});

describe("the printed legends", () => {
  /** Every part that sets type a reader has to read on the panel. */
  const LEGEND_PARTS = new Set([
    "faceplate-title",
    "lcd-tag",
    "lcd-value",
    "lcd-body",
    "led-legend",
    "key-legend",
    "rocker-legend",
    "slide-switch-legend",
    "fader-label",
    "dial-label",
  ]);

  /** WCAG 1.4.3: 4.5 : 1 for text under 18.66 px, 3 : 1 for the large figure the screen alone carries. */
  const floorFor = (size: number): number => (size >= 18.66 ? 3 : 4.5);

  /**
   * What a legend paints, measured the way a reader meets it: its colour over the surface it is printed on — the panel, the
   * cap of a key, the glass of a screen — with its opacity applied. A legend dimmed with `opacity` measures low here, which
   * is the point: a dim step is a colour, half an alpha is a defect.
   */
  const legendRatio = (element: HTMLElement): number => {
    const style = getComputedStyle(element);
    const backdrop = panelOf(element);
    return contrastRatio(painted(style.color, backdrop, opacityOf(element)), backdrop);
  };

  it("keeps every legend at 4.5 : 1 on the surface it is printed on (1.4.3)", () => {
    const { root } = mount(() => (
      <Faceplate title="Test unit">
        <Lcd tag="Level" value="40%">
          take 3
        </Lcd>
        <Led label="Signal present" legend="Sig" on />
        <Key label="Mute the output" legend="Mute" isToggle />
        <Rocker label="Power" offLabel="Off" onLabel="On" />
        <SlideSwitch label="Phantom power" offLabel="Off" onLabel="48V" />
        <Fader label="Level" min={0} max={100} defaultValue={40} />
        <Dial label="Tone" min={0} max={10} defaultValue={5} />
      </Faceplate>
    ));

    const measured: string[] = [];
    for (const element of root.querySelectorAll<HTMLElement>("[data-part]")) {
      const name = element.dataset.part ?? "";
      if (!LEGEND_PARTS.has(name)) {
        continue;
      }
      const text = (element.textContent ?? "").trim();
      if (text === "") {
        continue;
      }
      const size = Number.parseFloat(getComputedStyle(element).fontSize);
      const ratio = legendRatio(element);
      measured.push(name);
      expect(ratio, `${name} "${text}" at ${size}px`).toBeGreaterThanOrEqual(floorFor(size));
    }

    const value = part(root, "lcd-value");
    expect(Number.parseFloat(getComputedStyle(value).fontSize)).toBeGreaterThanOrEqual(18.66);

    for (const name of [
      "faceplate-title",
      "lcd-tag",
      "lcd-value",
      "lcd-body",
      "led-legend",
      "key-legend",
      "rocker-legend",
      "slide-switch-legend",
      "fader-label",
      "dial-label",
    ]) {
      expect(measured, name).toContain(name);
    }
  });

  it("keeps the cap's legend readable at every key colour (1.4.3)", () => {
    // the four the skin's own stories use, and the band the reference's 0.8 ink switch left at 3.35 : 1: a mid-light key
    const colours = [
      { l: 0.24, c: 0, h: 0 },
      { l: 0.45, c: 0.14, h: 255 },
      { l: 0.62, c: 0.2, h: 145 },
      { l: 0.86, c: 0.16, h: 96 },
    ].map((keyColor) => ({ keyColor }));

    const { root } = mount(() => (
      <For each={colours}>
        {(colour) => (
          <Faceplate keyColor={colour.keyColor}>
            <Key label="Mute the output" legend="Mute" isToggle />
            <Rocker label="Power" offLabel="Off" onLabel="On" defaultValue />
          </Faceplate>
        )}
      </For>
    ));

    const legends = [
      ...root.querySelectorAll<HTMLElement>(
        '[data-part="key-legend"], [data-part="rocker-legend"]',
      ),
    ];
    // two per faceplate: the key's cap and the rocker's two ends, one of which is the --key-cap chip
    expect(legends.length).toBeGreaterThanOrEqual(12);
    for (const legend of legends) {
      expect(
        legendRatio(legend),
        `${legend.textContent ?? ""} on ${panelOf(legend)}`,
      ).toBeGreaterThanOrEqual(4.5);
    }
  });
});

describe("the key", () => {
  it("is a button with a name, and its latch is the announced aria-pressed", async () => {
    const { root } = mount(() => (
      <Faceplate>
        <Key label="Mute the output" legend="Mute" isToggle />
        <Key label="Arm" />
      </Faceplate>
    ));
    const [latch, command] = [...root.querySelectorAll<HTMLElement>('[data-part="key"]')];
    expect(latch?.getAttribute("role")).toBe("button");
    expect(latch?.getAttribute("aria-label")).toBe("Mute the output");
    expect(latch?.getAttribute("aria-pressed")).toBe("false");
    expect(command?.hasAttribute("aria-pressed")).toBe(false);

    await userEvent.click(latch!);
    await frame();
    expect(latch?.getAttribute("aria-pressed")).toBe("true");
    expect(part(root, "key-legend").textContent).toBe("Mute");
  });

  it("moves the cap, not the hole, when it latches", async () => {
    const { root } = mount(() => (
      <Faceplate>
        <Key label="Hold" legend="Hold" isToggle />
      </Faceplate>
    ));
    const hole = part(root, "key");
    const cap = part(root, "key-face");
    const rest = getComputedStyle(cap).translate;
    // one number drives both: --lift is the travel at rest, 0 latched
    expect(lift(hole)).toBe("10px");

    await userEvent.click(hole);
    // the cap travels down into the hole rather than jumping: the one registered property is what the transition walks
    await waitFor(() => lift(hole) === "0px");
    expect(hole.getAttribute("aria-pressed")).toBe("true");
    expect(getComputedStyle(cap).translate).not.toBe(rest);
  });

  it("travels back to the raised position when a command key lets go", async () => {
    const { root } = mount(() => (
      <Faceplate>
        <Key label="Arm" />
      </Faceplate>
    ));
    const hole = part(root, "key");
    const travel = lift(hole);
    await userEvent.click(hole);
    await frame();
    expect(hole.hasAttribute("aria-pressed")).toBe(false);
    await waitFor(() => lift(hole) === travel);
  });

  it("rings its hole in outline, 3 : 1 against the panel it stands on", async () => {
    const { root } = mount(() => (
      <Faceplate>
        <Key label="Arm" />
      </Faceplate>
    ));
    const hole = await tabTo(root, "key");
    const style = getComputedStyle(hole);
    // an outline, not a shadow: the hole's overflow clips a shadow ring
    expect(style.outlineStyle).toBe("solid");
    expect(parseFloat(style.outlineWidth)).toBeGreaterThanOrEqual(2);
    expect(style.boxShadow).not.toContain(style.outlineColor);
    expect(contrastRatio(style.outlineColor, panelOf(hole))).toBeGreaterThanOrEqual(3);
  });
});

describe("the fader", () => {
  it("puts the slider on the cap and the value on the thumb", () => {
    const { root } = mount(() => (
      <Faceplate>
        <Fader label="Level" min={0} max={100} defaultValue={40} />
      </Faceplate>
    ));
    const cap = part(root, "fader-cap");
    expect(cap.getAttribute("role")).toBe("slider");
    expect(cap.getAttribute("aria-label")).toBe("Level");
    expect(cap.getAttribute("aria-valuenow")).toBe("40");
    expect(cap.getAttribute("aria-valuemin")).toBe("0");
    expect(cap.getAttribute("aria-valuemax")).toBe("100");
    // the cap and the fill are placed by one number, written on the groove from the value the thumb announces
    expect(part(root, "fader-track").style.getPropertyValue("--at")).toBe("40");
  });

  it("steps the value with the arrow keys and moves the cap with it", async () => {
    const { root } = mount(() => (
      <Faceplate>
        <Fader label="Level" min={0} max={100} defaultValue={40} />
      </Faceplate>
    ));
    const cap = part(root, "fader-cap");
    cap.focus();
    await frame();

    await userEvent.keyboard("{ArrowRight}");
    await frame();
    expect(cap.getAttribute("aria-valuenow")).toBe("41");
    expect(part(root, "fader-track").style.getPropertyValue("--at")).toBe("41");

    await userEvent.keyboard("{Home}");
    await frame();
    expect(cap.getAttribute("aria-valuenow")).toBe("0");
