    const style = getComputedStyle(cap);
    expect(style.outlineStyle).toBe("solid");
    expect(parseFloat(style.outlineWidth)).toBeGreaterThanOrEqual(2);
    expect(contrastRatio(style.outlineColor, panelOf(cap))).toBeGreaterThanOrEqual(3);
  });
});

describe("the layout", () => {
  // Geometric invariants, not a pixel snapshot: a snapshot breaks on a font or a platform, while "a key is not on top of
  // the key beside it" is true at every size and says what broke. An sr-only value and an absolutely positioned layer are
  // not findings; the rule is about the flow.
  const SLACK = 1;
  const outOfSight = (element: HTMLElement): boolean => {
    const style = getComputedStyle(element);
    return style.clipPath === "inset(50%)" || style.clip === "rect(0px, 0px, 0px, 0px)";
  };
  const inFlow = (element: HTMLElement): boolean => {
    const position = getComputedStyle(element).position;
    return position !== "absolute" && position !== "fixed";
  };

  const inside = (inner: DOMRect, outer: DOMRect): boolean =>
    inner.left >= outer.left - SLACK &&
    inner.top >= outer.top - SLACK &&
    inner.right <= outer.right + SLACK &&
    inner.bottom <= outer.bottom + SLACK;

  const overlap = (a: DOMRect, b: DOMRect): boolean =>
    Math.min(a.right, b.right) - Math.max(a.left, b.left) > SLACK &&
    Math.min(a.bottom, b.bottom) - Math.max(a.top, b.top) > SLACK;

  const findingsIn = (root: HTMLElement): ReadonlyArray<string> => {
    const findings: string[] = [];
    const parts = [...root.querySelectorAll<HTMLElement>("[data-part]")];
    const parentOf = (element: HTMLElement): HTMLElement | null =>
      element.parentElement?.closest<HTMLElement>("[data-part]") ?? null;
    const siblings = new Map<HTMLElement | null, HTMLElement[]>();

    for (const element of parts) {
      const name = element.dataset["part"] ?? "?";
      const parent = parentOf(element);
      const list = siblings.get(parent) ?? [];
      list.push(element);
      siblings.set(parent, list);

      if (element.hidden || element.getClientRects().length === 0 || outOfSight(element)) {
        continue;
      }
      const rect = element.getBoundingClientRect();
      if (rect.width < 2 || rect.height < 2) {
        findings.push(`${name} has no box (${Math.round(rect.width)}x${Math.round(rect.height)})`);
      }
      // A flow box belongs inside the part it sits on; a layer may hang past it on purpose.
      if (parent !== null && inFlow(element) && !inside(rect, parent.getBoundingClientRect())) {
        findings.push(`${name} spills out of ${parent.dataset["part"] ?? "?"}`);
      }
    }

    for (const [, group] of siblings) {
      for (let a = 0; a < group.length; a += 1) {
        for (let b = a + 1; b < group.length; b += 1) {
          const first = group[a];
          const second = group[b];
          if (first === undefined || second === undefined) continue;
          if (!inFlow(first) || !inFlow(second)) continue;
          if (overlap(first.getBoundingClientRect(), second.getBoundingClientRect())) {
            findings.push(
              `${first.dataset["part"] ?? "?"} overlaps ${second.dataset["part"] ?? "?"}`,
            );
          }
        }
      }
    }
    return findings;
  };

  it("keeps every part in its place on the whole instrument", async () => {
    const { root } = mount(() => <Device />);
    await frame();
    expect(findingsIn(root)).toEqual([]);
  });

  it("keeps every part in its place on a row of parts", async () => {
    const { root } = mount(() => (
      <Faceplate title="Row">
        <div data-part="row">
          <Key label="One" legend="1" />
          <Key label="Two" legend="2" />
          <Led label="Lit" legend="Sig" on />
          <Fader label="Level" min={0} max={100} value={40} />
          <Dial label="Tone" min={0} max={10} step={1} value={5} />
        </div>
      </Faceplate>
    ));
    await frame();
    expect(findingsIn(root)).toEqual([]);
  });
});

import solid from "@solidjs/vite-plugin";
import cssints, { targets } from "cssints/vite";
import { defineConfig } from "vite-plus";
import { playwright } from "vite-plus/test/browser-playwright";

// The conformance test a starter arrives with runs in a real Chromium: the scenario walk needs a
// real DOM and Solid 2's reactivity, not a simulated one.
export default defineConfig({
  // `evaluation.inline`: a browser-mode runner inlines everything as ESM, so the plugin's own
  // evaluation server keeps the framework's packages inlined (Solid resolves its client build by
  // them) and the rest external (Node loads their CJS). Without it, a click's target resolves
  // against a second copy of Solid and the walk reads a state the page never changed.
  plugins: [
    cssints({ evaluation: { inline: ["solid-js", "@solidjs/web", "@solidjs/signals"] } }),
    solid(),
  ],
  css: { transformer: "lightningcss", lightningcss: { targets } },
  // The plugin adds `import derived from "cssints/derived"` to a client module after the dep
  // scanner has run; pre-bundling it here is what keeps that from reloading the page mid-test.
  optimizeDeps: { include: ["cssints/derived"] },
  test: {
    // a browser test has no app entry: the sheet of the modules the test imports arrives through
    // `virtual:cssints.css`, and vitest drops CSS imports unless it is told to process them
    css: true,
    // the sheet is loaded by the test's imports, not before them
    setupFiles: ["src/sheet.ts"],
    include: ["src/components/ui/**/*.browser.test.tsx"],
    browser: {
      enabled: true,
      provider: playwright(),
      headless: true,
      viewport: { width: 1280, height: 1024 },
      instances: [{ browser: "chromium" }],
      // The default waits 60 s for a worker's iframe to come up, which a busy machine (or a CI runner with a dozen other
      // jobs) misses: the run then fails as `the iframe did not become ready` with no test having run. Nothing about a
      // test gets longer; this is the browser starting.
      connectTimeout: 120_000,
      // the iframe ready timeout is read from the config's own env, not from the process that started the run
      env: { VITEST_BROWSER_IFRAME_TIMEOUT: "120000" },
    },
  },
});

// The engine's sheet for a browser test: its content is the CSS of the modules transformed so far, so it is loaded once the
// test file's imports are in (in `beforeAll`, not as a static import: vitest resolves the graph as it goes, and a sheet loaded
// first is just the `@layer` statement). A component's conformance test clicks its parts, so the sheet has to be there.
import { beforeAll } from "vite-plus/test";

beforeAll(async () => {
  await import("virtual:cssints.css");
});
